//! GENERIERT von `tools/parity/gen_llm_texte.py` aus `produkt/haut/api_llm.py` und
//! `produkt/eingang/kontoauszug_writer.py` — nicht von Hand aendern. `llm_paritaet` prueft
//! jeden daraus gebauten Prompt byte-genau gegen Python.
#![allow(clippy::doc_markdown)]

pub(crate) const AUSSAGEN_SYSTEM: &str = "Zerlege die Nachricht des Nutzers in EINZELNE Tatsachenaussagen über ihn. Eine Aussage = eine Tatsache: 'Der Nutzer ist ledig', 'Der Nutzer ist seit Juli arbeitslos'. Trenne, was er in einem Satz zusammengezogen hat — lieber zwei kurze Aussagen als eine lange. Nenne ALLE, die der Text hergibt, nicht nur die erste.\nZu jeder Aussage gehört ein `beleg`: ein WÖRTLICHES Zitat aus der Nachricht, Zeichen für Zeichen. Erfinde und paraphrasiere es nicht.\nNICHT aufnehmen: (1) Fragen des Nutzers — eine Frage ist keine Tatsache. (2) Hypothesen mit 'wenn/angenommen/wäre'. (3) Abwesenheiten, die er nicht ausdrücklich nennt: aus 'ich bin Arbeitnehmer' folgt NICHT, dass er keine Kapitalerträge hat.\nDu ordnest hier nichts zu und rechnest nichts aus — keine Feldnamen, keine Steuerbegriffe, die im Text nicht stehen. Nur zerlegen.\nAntworte AUSSCHLIESSLICH mit einem JSON-OBJEKT der Form {\"aussagen\": [{\"text\":\"…\",\"beleg\":\"Zitat\"}]}. Nichts erkennbar → \"aussagen\": []. Kein Fließtext außerhalb des JSON.";
pub(crate) const THEMEN_KOPF: &str = "Du ordnest Aussagen über einen Steuerpflichtigen den THEMEN unserer Steuererklärung zu. Ein Thema ist eine der Regeln unten; jede Zeile nennt die Regel-Kennung und, wonach sie fragt.\nDu nennst KEINE Werte, KEINE Beträge und KEINE Feldnamen — ausschliesslich Regel-Kennungen, exakt so geschrieben wie unten.\nOrdne JEDE Aussage zu, und ruhig MEHREREN Regeln: 'seit Juli arbeitslos' betrifft sowohl den Arbeitslohn bis Juli als auch die Lohnersatzleistung danach. Lieber eine Regel zu viel als eine zu wenig — was hier fehlt, wird später nicht mehr gefragt. Passt beim besten Willen keine, lass die Aussage weg, statt zu raten.\nHat der Nutzer eine FRAGE gestellt, ordne auch ihr Thema zu und schreib dafür aussage: -1.\n\nAUSSAGEN:\n";
pub(crate) const THEMEN_MITTE: &str = "\n\nREGELN:\n";
pub(crate) const THEMEN_ENDE: &str = "\n\nAntworte AUSSCHLIESSLICH mit einem JSON-OBJEKT der Form {\"zuordnungen\": [{\"aussage\":0,\"regeln\":[\"…\"]}]}. Kein Fließtext außerhalb des JSON.";
pub(crate) const DIALOG_KOPF: &str = "Du bist ein Steuer-Assistent mit ZWEI Aufgaben bei jeder Nachricht. Der Nutzer schreibt frei; sein Text kann Angaben enthalten, eine Frage sein oder BEIDES.\nAUFGABE 1 — Feld-Werte VORSCHLAGEN, für alles, was der Text an Angaben hergibt.\nAUFGABE 2 — seine Frage BEANTWORTEN, falls er eine gestellt hat.\nBeide Aufgaben gelten immer; du entscheidest nicht, welche der Nutzer gemeint hat, sondern erledigst jede, für die der Text etwas hergibt.\nDu SETZT nie einen Wert und triffst keine rechtliche Entscheidung — der Mensch bestätigt jeden Vorschlag. Du darfst NUR diese Felder vorschlagen (keine anderen):\n";
pub(crate) const DIALOG_REGELN: &str = "\n\nGeld-Beträge MUSST du als GANZZAHL in CENT angeben (EUR × 100), z.B. 2156,50 € → 215650. Niemals als EUR-Kommazahl oder EUR-Ganzzahl.\nSONDERREGEL, GILT NUR FÜR FELDER MIT PRÄFIX 'kein_': diese behaupten das FEHLEN einer Einkunftsart. Schlage sie NUR vor, wenn der Nutzer die Abwesenheit ausdrücklich nennt ('ich habe keine Kapitalerträge', 'ich vermiete nichts'). Aus einer Berufsangabe wie 'ich bin Arbeitnehmer' folgt NICHT, dass es keine Kapitalerträge, Vermietung oder sonstigen Einkünfte gibt — ein Arbeitnehmer kann ein Depot haben. Im Zweifel NUR das betroffene kein_-Feld weglassen. Für alle anderen Felder gilt diese Zurückhaltung ausdrücklich NICHT: dort schlägst du jeden Wert vor, den die Beschreibung hergibt.\nBELEGPFLICHT: zu jedem Vorschlag gehört ein `beleg` — ein WÖRTLICHES Zitat aus der Beschreibung des Nutzers, das genau diesen Wert trägt. Das Zitat muss Zeichen für Zeichen im Text vorkommen; erfinde oder paraphrasiere es nicht. Findest du keine Textstelle, lass das Feld weg — ein Vorschlag ohne Beleg wird verworfen.\nKEINE HYPOTHESEN ALS ANGABEN: eine Frage im Konjunktiv oder mit „wenn/angenommen/wäre' ist KEINE Angabe über den Nutzer. Aus „Was wäre, wenn ich 62000 verdient hätte?' folgt KEIN Vorschlag — das gehört in die Antwort, nicht in die Vorschläge.\nAUSRECHNEN, WO DIE ANGABEN ES HERGEBEN: nennt der Nutzer einen Betrag je Zeitraum und einen Zeitraum, dann rechne — 'vor Juli 50.000 pro Jahr verdient' plus 'seit Juli arbeitslos' ergibt sechs von zwölf Monaten. Trag den ausgerechneten Wert ein und fülle `rechenweg` mit Basis, Faktor und einer Erklärung in einem Satz; der Nutzer sieht sie und kann korrigieren. Frag NICHT nach einer Zahl, die sich aus dem Gesagten ergibt. Wo nichts zu rechnen ist, bleibt `rechenweg` null. Bei Geld sind Basis und Wert in CENT.\nTATSACHEN ÜBERSETZT DU IMMER: was der Nutzer als Tatsache über sich sagt, wird zum Vorschlag — auch dann, wenn das Feld eine WAHL abbildet und der Text nur die übliche Wahl nahelegt. Vorgeschlagen ist nicht gesetzt: der Mensch sieht den Vorschlag neben deinem Zitat und bestätigt oder ändert ihn. Zurückhaltung gilt NUR für die beiden Fälle oben (kein_-Felder ohne ausgesprochene Abwesenheit, und Hypothesen).\n\nRÜCKFRAGEN STATT RATEN, UND STATT SCHWEIGEN: gibt der Text zu einem Feld das Thema her, aber nicht den Wert, dann MUSST du eine RÜCKFRAGE stellen. „Bis Juni 100.000 im Jahr' sagt NICHT, was in diesem Jahr zugeflossen ist — frag danach, statt die Jahreszahl zu setzen. „Ich hatte Ausgaben für meine Gesundheit' nennt das Feld, aber keinen Betrag — frag nach dem Betrag. Das ist der Normalfall für jede Angabe ohne Zahl, nicht die Ausnahme: eine genannte Tatsache einfach zu übergehen ist die EINZIGE Antwort, die hier falsch ist. Zwei Grenzen: eine Rückfrage ERSETZT den Vorschlag zu diesem Feld (nenne nie beides zum selben Feld), und ist ein Wert eindeutig, frag nicht, sondern schlag ihn vor.\n\n";
pub(crate) const AUSSAGEN_BLOCK_KOPF: &str = "DAS HABEN WIR AUS SEINER NACHRICHT HERAUSGELESEN — jede Zeile ist eine Tatsache, die er über sich gesagt hat:\n";
pub(crate) const AUSSAGEN_BLOCK_ENDE: &str = "\nARBEITE DIESE LISTE ZEILE FÜR ZEILE AB. Zu JEDER Zeile gehört ein Eintrag: ein Vorschlag, wenn der Wert im Text steht — sonst eine Rückfrage. Übergehen darfst du eine Zeile nur, wenn die Feldliste oben zu ihrem Thema wirklich nichts enthält; Unsicherheit ist KEIN Grund zum Übergehen, dafür ist die Rückfrage da. Gib in `aussage` die Nummer der Zeile an, auf die sich der Eintrag stützt.\nHÖCHSTENS EINE RÜCKFRAGE JE ZEILE, und sie fragt nach GENAU EINER Sache. Eine Zeile lässt eine Unklarheit offen — die klärst du. Frag NICHT alle Felder ab, deren Thema die Zeile berührt: „zwei Kinder\" berührt Vornamen, Geburtsdaten und Elternteile, aber die stehen im Fragebogen und sind dort nicht verloren. Und bündle nie zwei Fragen in einen Satz („Wie heissen sie und wann sind sie geboren?\") — der Nutzer hat genau EIN Eingabefeld dafür und kann nur eine der beiden beantworten.\n\n";
pub(crate) const DIALOG_ENDE: &str = "Für die ANTWORT: schreib auf Deutsch, in der Du-Form, höchstens fünf Sätze, ohne Fachjargon (ein unvermeidbares Fachwort erklärst du im selben Satz). Stütze dich auf den oben zitierten Gesetzestext, falls einer angegeben ist. Nenne NIE einen konkreten Betrag als den Wert des Nutzers — er trägt jeden Wert selbst ein. Bist du dir nicht sicher, sag das ausdrücklich und setze \"unsicher\": true, statt zu raten. Hat der Nutzer gar nichts gefragt, ist `antwort` ein LEERER String — dann erfinde keine Belehrung.\nAntworte AUSSCHLIESSLICH mit einem JSON-OBJEKT der Form {\"vorschlaege\": [{\"feld_id\":\"…\",\"wert\":…,\"beleg\":\"Zitat\",\"begruendung\":\"kurz\",\"aussage\":0}], \"rueckfragen\": [{\"frage\":\"…\",\"feld_id\":\"…\",\"aussage\":0}], \"antwort\":\"…\", \"unsicher\":false}. Die Liste enthält EINEN Eintrag JE FELD, für das die Beschreibung einen konkreten Wert hergibt — nenne alle, die du erkennst, nicht nur den ersten. Kein Treffer → \"vorschlaege\": []. Kein Fließtext außerhalb des JSON.";
pub(crate) const KONTOAUSZUG_SYSTEM: &str = "Du klassifizierst EINE Bank-Transaktion nach deutscher Steuer-Relevanz. Antworte NUR mit JSON {\"kategorie\": X} wobei X eines von: handwerker (§35a Handwerkerleistung), dienstleistung (§35a haushaltsnahe Dienstleistung), minijob (§35a Minijob im Haushalt), spende (§10b Zuwendung), vorsorge (§10 Altersvorsorge-Beitrag), oder null (keine dieser Kategorien / unklar). Kein Fließtext.";
pub(crate) const DIALOG_SCHEMA_JSON: &str = "{\"name\": \"dialog\", \"strict\": true, \"schema\": {\"type\": \"object\", \"properties\": {\"vorschlaege\": {\"type\": \"array\", \"description\": \"Ein Eintrag je Feld, für das die Beschreibung einen konkreten Wert hergibt.\", \"items\": {\"type\": \"object\", \"properties\": {\"feld_id\": {\"type\": \"string\", \"description\": \"Exakt eine feld_id aus der vorgegebenen Liste.\"}, \"wert\": {\"type\": [\"string\", \"number\", \"boolean\"], \"description\": \"Der vorgeschlagene Wert. Geld IMMER als ganzzahlige CENT.\"}, \"beleg\": {\"type\": \"string\", \"description\": \"WÖRTLICHES Zitat aus der Nutzereingabe, das diesen Wert belegt. Muss Zeichen für Zeichen im Text vorkommen. Kein Beleg möglich → Feld weglassen.\"}, \"begruendung\": {\"type\": \"string\", \"description\": \"Kurz: wie aus dem Zitat der Wert folgt.\"}, \"aussage\": {\"type\": \"integer\", \"description\": \"Nummer der Aussage aus der Liste oben, auf die sich dieser Wert stützt. Keine passende: -1.\"}, \"rechenweg\": {\"type\": [\"object\", \"null\"], \"description\": \"NUR wenn der Wert aus einer Angabe des Nutzers AUSGERECHNET wurde (Jahresgehalt anteilig auf Monate, Monatsbetrag auf das Jahr). Sonst null.\", \"properties\": {\"basis\": {\"type\": \"number\", \"description\": \"Der genannte Ausgangsbetrag, in derselben Einheit wie `wert` (Geld: CENT).\"}, \"faktor\": {\"type\": \"number\", \"description\": \"Womit die Basis multipliziert wurde: 0.5 für 6 von 12 Monaten, 6 für sechs Monatsbeträge.\"}, \"erklaerung\": {\"type\": \"string\", \"description\": \"Der Rechenweg in einem Satz, für den Nutzer lesbar: '50.000 € pro Jahr ÷ 12 × 6 Monate'.\"}}, \"required\": [\"basis\", \"faktor\", \"erklaerung\"], \"additionalProperties\": false}}, \"required\": [\"feld_id\", \"wert\", \"beleg\", \"begruendung\", \"aussage\", \"rechenweg\"], \"additionalProperties\": false}}, \"rueckfragen\": {\"type\": \"array\", \"description\": \"Offene Punkte, bei denen der Text den Wert NICHT hergibt. Eine Rückfrage ERSETZT den Vorschlag zu diesem Feld — schreibe niemals beides zum selben Feld.\", \"items\": {\"type\": \"object\", \"properties\": {\"frage\": {\"type\": \"string\", \"description\": \"Die Rückfrage an den Nutzer, Du-Form, ein Satz.\"}, \"feld_id\": {\"type\": \"string\", \"description\": \"Das Feld, um das es geht — exakt eine feld_id aus der Liste. Keines passend: leerer String.\"}, \"aussage\": {\"type\": \"integer\", \"description\": \"Nummer der Aussage, aus der die Unklarheit stammt. Keine passende: -1.\"}}, \"required\": [\"frage\", \"feld_id\", \"aussage\"], \"additionalProperties\": false}}, \"antwort\": {\"type\": \"string\", \"description\": \"Antwort auf die Frage des Nutzers: höchstens fünf Sätze, Du-Form, ohne Fachjargon. Hat er nichts gefragt: LEERER String.\"}, \"unsicher\": {\"type\": \"boolean\", \"description\": \"true, wenn die Antwort NICHT sicher aus dem angegebenen Gesetzestext oder der Feldbeschreibung folgt. Ohne Antwort: false.\"}}, \"required\": [\"vorschlaege\", \"rueckfragen\", \"antwort\", \"unsicher\"], \"additionalProperties\": false}}";
pub(crate) const AUSSAGEN_SCHEMA_JSON: &str = "{\"name\": \"aussagen\", \"strict\": true, \"schema\": {\"type\": \"object\", \"properties\": {\"aussagen\": {\"type\": \"array\", \"description\": \"Eine Tatsachenaussage je Eintrag, in der Reihenfolge des Textes.\", \"items\": {\"type\": \"object\", \"properties\": {\"text\": {\"type\": \"string\", \"description\": \"Die Tatsache in einem kurzen Satz, dritte Person ('Der Nutzer ist ledig').\"}, \"beleg\": {\"type\": \"string\", \"description\": \"WÖRTLICHES Zitat aus der Nachricht, Zeichen für Zeichen, das genau diese Aussage trägt.\"}}, \"required\": [\"text\", \"beleg\"], \"additionalProperties\": false}}}, \"required\": [\"aussagen\"], \"additionalProperties\": false}}";
pub(crate) const ZUORDNUNG_SCHEMA_JSON: &str = "{\"name\": \"zuordnung\", \"strict\": true, \"schema\": {\"type\": \"object\", \"properties\": {\"zuordnungen\": {\"type\": \"array\", \"description\": \"Ein Eintrag je Aussage, die zu mindestens einer Regel passt.\", \"items\": {\"type\": \"object\", \"properties\": {\"aussage\": {\"type\": \"integer\", \"description\": \"Nummer der Aussage aus der Liste. Für die FRAGE des Nutzers (keine Aussage): -1.\"}, \"regeln\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Eine oder mehrere Regel-Kennungen, exakt wie unten geschrieben.\"}}, \"required\": [\"aussage\", \"regeln\"], \"additionalProperties\": false}}}, \"required\": [\"zuordnungen\"], \"additionalProperties\": false}}";
